    for col in ['H','I','J']:
        if r==3:
            key='C'
        elif r==4:
            key='B'
        elif r==5:
            key='C'
        else:
            key='B'
        colnum = {'H':7,'I':8,'J':9}[col]
        ws[f'{col}{r}'] = f'=VLOOKUP({key}{r},Grouping!\$A\$2:\$I\$7,{colnum},FALSE)'
wb.save('output.xlsx')
print('done')
"

